"""widget.py — the moy-1 figure as a native anywidget (no iframe). The front-end (pages/widget.js, pages/widget.css) is generated by build.mjs.

    from widget import CoreadFigure
    w = CoreadFigure(state=0)                # JupyterLab: put `w` at the end of a cell.   marimo: mo.ui.anywidget(w)
    w.state = 8                              # kernel -> figure: walk to state 8 (blocked: the ten bands)
    w.t = 3; w.lang = "en"; w.theme = "light"   # t = the focus index of the state (a row 0-9 in states 4-10; a position 0-15 in states 13-14; a token in states 18-19; 0-63 in state 20)
    w.goto_chapter("sae")                    # v2: the chapter "construction x SAE trajectory" (v3: states 18-25 incl. the slope state 22 and olm62 = 23-24) · w.goto_chapter("tree") = the map of the card tree (state 26) · w.goto_chapter("flow") = the part added after the 10-28 figure (states 27-36)
    w.state, w.t, w.done                     # figure -> kernel: what the reader pressed / slid, and whether the figure has stopped moving
    w.reading                                # figure -> kernel: what is on the screen, as text and numbers (kicker, readout, chips)
    w.check_counts()                         # the kernel's own recount (from generated/pack.json) against the numbers the screen shows (a third route)
Both directions are tested (run_marimo_check.sh, run_jupyter_check.sh): a trait the figure writes must come back as a number in Python, and a number written in Python must move the figure.
"""
import json
import pathlib

import anywidget
import traitlets

HERE = pathlib.Path(__file__).resolve().parent
CONFIG = json.loads((HERE / "config.json").read_text(encoding="utf-8"))
STATES = CONFIG["chapters"][-1][2] + 1        # the number of states is never typed: it is the last state of the last chapter in config.json
CHAPTERS = {name: (a, b) for name, a, b in CONFIG["chapters"]}


class CoreadFigure(anywidget.AnyWidget):
    _esm = HERE / "pages" / "widget.js"
    _css = HERE / "pages" / "widget.css"

    # both ways: the reader's hands and Python's writes
    state = traitlets.Int(0).tag(sync=True)
    lang = traitlets.Enum(["ja", "en"], default_value="ja").tag(sync=True)
    t = traitlets.Int(-1).tag(sync=True)                       # -1 = follow the state; else the focus index of the figure (a row 0-9 / a position 0-15)
    theme = traitlets.Enum(["dark", "light", "auto"], default_value="dark").tag(sync=True)
    # figure -> kernel (owned by the figure)
    done = traitlets.Bool(True).tag(sync=True)                 # the figure has stopped moving (a capture or a check waits for it)
    reading = traitlets.Dict({}).tag(sync=True)                # {state, chapter, lang, t, kicker, readout, chips, quote}

    @traitlets.validate("state")
    def _clamp_state(self, proposal):
        return max(0, min(STATES - 1, int(proposal["value"])))

    def goto_chapter(self, name):
        """kernel -> figure: the first state of a chapter (problem / prompts / open / blocked / moment / models / sae / tree / flow / l3 / space / struct / apex / next / ledger)."""
        self.state = CHAPTERS[name][0]

    def check_counts(self):
        """The kernel's recount: the numbers of generated/pack.json (written by pack_moy1.py from the frozen files) against what the screen of the figure reports in `reading`.
        Returns {state: (what the screen says, what Python counted, equal)}; it reads the screen as the figure's own text, so it also fails if the page and the pack drift apart."""
        pack = json.loads((HERE / "generated" / "pack.json").read_text(encoding="utf-8"))
        o, t5 = pack["olm59"], pack["olm59"]["cmt5_two"]
        pair = lambda R, gi: f"{R['before'][gi]:.2f} → {R['after'][gi]:.2f}"            # the figure's chips print before → after to 2 decimals
        bd = lambda p_, k: t5[p_][k]["B-bind"]
        import os
        r62 = json.loads((pathlib.Path(os.environ.get("MOY1_REPO", HERE / "data")) / "ConstructGap/exp/olm62/read.json").read_text(encoding="utf-8"))
        mid = o["agg"]["o_diam"]["groups"]["mid"]["all"]
        rd = lambda c, f="read.json": json.loads((pathlib.Path(os.environ.get("MOY1_REPO", HERE / "data")) / f"ConstructGap/exp/{c}/{f}").read_text(encoding="utf-8"))
        r76, c76, r128 = rd("olm76"), rd("olm76", "control.json"), rd("olm128")
        want = {4: [f"{pack['open_cnt']['bare']} / 10", f"{pack['o_sent']['open']} / 10", f"{pack['he_sent']['open']} / 10"],
                18: [f"token {o['S_O']['event']}"] + [pair(o["S_O"], gi) for gi in (1, 2, 0)],       # the four chips of the state: the first naming token and mid / answer side / close (the thought side is in the readout and the lead)
                19: [f"token {o['S_H']['event']}"] + [pair(o["S_H"], gi) for gi in (1, 2, 0)],
                20: [pair(o["S_O"], 1), pair(o["S_O"], 2), pair(o["S_H"], 1), pair(o["S_H"], 2)],
                21: [f"{o['Q1']['up']} / {o['Q1']['n']}", f"{o['Q2']['up']} / {o['Q2']['n']}", f"{mid['up']} / {mid['n']}"],
                22: [f"{mid['up']} / {mid['n']}", f"{o['agg']['h_diam']['groups']['mid']['all']['up']} / {o['agg']['h_diam']['groups']['mid']['all']['n']}"],                  # v3: the slope state's first two chips (the mid group's rise in the 59 and the 34 rows)
                23: [f"{r62['o_diam']['math_up']} / {r62['o_diam']['n']}", f"{r62['h_diam']['math_up']} / {r62['h_diam']['n']}"],                       # v2.1: olm62 counted from the card's own read.json (not through the pack)
                24: [r62["Q2"]["o_diam_mid_up_when_math_flat"]],
                28: [f"{r76['Q1_bind_close_rises']['pos']} / {r76['Q1_bind_close_rises']['n']}", f"{c76['C2_pseudo_window']['sae_close']['pos']} / {c76['C2_pseudo_window']['sae_close']['n']}", f"{r76['desc_all_keys']['sae_close|attractor']['pos']} / {r76['desc_all_keys']['sae_close|attractor']['n']}"],      # v3 (a): olm76 counted from the card's own files
                35: [f"11 / {r128['verdicts']['Q1_N']} = {r128['verdicts']['Q1_concordance']:.3f}"],
                25: [f"{bd('think', 'full')} → {bd('think', 'field')} / {t5['think']['n']}", f"{bd('answer', 'full')} → {bd('answer', 'field')} / {t5['answer']['n']}", f"{bd('natural', 'full')} → {bd('natural', 'field')} / {t5['natural']['n']}"],
                8: [f"attractor {len(pack['json_first']['blocked'])} / {len(pack['json_first']['blocked'])}", f"bind {10 - len(pack['json_first']['blocked'])} / {10 - len(pack['json_first']['blocked'])}"],
                9: [f"{pack['o_sent']['open']} → {pack['o_sent']['blocked']} / 10", f"{pack['he_sent']['open']} → {pack['he_sent']['blocked']} / 10"]}.get(self.state)
        if want is None:
            return {"state": self.state, "note": "no recount is defined for this state"}
        have = [c["v"] for c in self.reading.get("chips", [])]
        return {"state": self.state, "screen": have, "python": want, "equal": all(x in have for x in want)}
